import{_ as a,o,c as t,a3 as i}from"./chunks/framework.DAK02U1-.js";const f=JSON.parse('{"title":"FAQ and troubleshooting","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"FAQ and troubleshooting | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/guide/faq"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/guide/faq"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/guide/faq"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/guide/faq"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/guide/faq"}]]},"headers":[],"relativePath":"xclang/guide/faq.md","filePath":"en/xclang/guide/faq.md","lastUpdated":1791227177000}'),n={name:"xclang/guide/faq.md"};function s(r,e,d,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="faq-and-troubleshooting" tabindex="-1">FAQ and troubleshooting <a class="header-anchor" href="#faq-and-troubleshooting" aria-label="Permalink to &quot;FAQ and troubleshooting&quot;">​</a></h1><p>The things that surprise people, by symptom.</p><h2 id="linking-and-running" tabindex="-1">Linking and running <a class="header-anchor" href="#linking-and-running" aria-label="Permalink to &quot;Linking and running&quot;">​</a></h2><h3 id="a-std-exception-from-my-shared-library-is-not-caught" tabindex="-1">A <code>std::exception</code> from my shared library is not caught <a class="header-anchor" href="#a-std-exception-from-my-shared-library-is-not-caught" aria-label="Permalink to &quot;A `std::exception` from my shared library is not caught&quot;">​</a></h3><p>On Linux and macOS, a standard exception thrown in one shared library and caught in another is caught by <code>catch (...)</code>, not by <code>catch (const std::exception&amp;)</code>. Every shared object linked by xclang has its own libc++, and so its own <code>type_info</code> for <code>std::exception</code>, which libc++ compares by address there. Windows compares by name and catches it. Link the code into one program, or keep C++ types and exceptions inside each shared object behind a C interface (<a href="./../design/hermeticity#one-libc-per-shared-object">one libc++ per shared object</a>).</p><h3 id="bazel-tests-crash-at-start-up-with-a-double-free" tabindex="-1">Bazel tests crash at start-up with a double free <a class="header-anchor" href="#bazel-tests-crash-at-start-up-with-a-double-free" aria-label="Permalink to &quot;Bazel tests crash at start-up with a double free&quot;">​</a></h3><p>Bazel links <code>cc_library</code> dependencies of tests into shared objects by default, each with its own libc++. xclang&#39;s module turns that off (<code>supports_dynamic_linker</code>); if a target turned it back on, take it off again, or make sure no C++ object crosses those shared objects (<a href="./../integrations/bazel#what-the-toolchain-does">Bazel</a>).</p><h3 id="undefined-references-to-std-cxx11-or-std-1" tabindex="-1">Undefined references to <code>std::__cxx11::...</code> or <code>std::__1::...</code> <a class="header-anchor" href="#undefined-references-to-std-cxx11-or-std-1" aria-label="Permalink to &quot;Undefined references to `std::__cxx11::...` or `std::__1::...`&quot;">​</a></h3><p>A C++ library built with GCC&#39;s libstdc++ (a distribution&#39;s Qt, Boost, ...) or with MSVC&#39;s STL is being linked into a program built with xclang&#39;s libc++: the two standard libraries are different ABIs. Build C++ dependencies with xclang for the same target (CMake, Bazel, vcpkg with xclang&#39;s toolchain file chain-loaded). C libraries are not affected.</p><h3 id="version-glibc-2-34-not-found-on-an-older-machine" tabindex="-1">&quot;version `GLIBC_2.34&#39; not found&quot; on an older machine <a class="header-anchor" href="#version-glibc-2-34-not-found-on-an-older-machine" aria-label="Permalink to &quot;&quot;version `GLIBC_2.34&#39; not found&quot; on an older machine&quot;">​</a></h3><p>A program from xclang links against glibc 2.17 and needs nothing newer, unless something in the link was built against a newer glibc: a shared library from the build machine (<code>-L/usr/lib/...</code>), or a build with <code>--no-default-config</code>, which uses the machine&#39;s own glibc. Link only libraries built with xclang for the target. <code>llvm-readobj --needed-libs</code> and <code>llvm-objdump -T</code> show what a program asks for.</p><h3 id="static-pie-fails-or-pg-does-not-link" tabindex="-1"><code>-static-pie</code> fails, or <code>-pg</code> does not link <a class="header-anchor" href="#static-pie-fails-or-pg-does-not-link" aria-label="Permalink to &quot;`-static-pie` fails, or `-pg` does not link&quot;">​</a></h3><p>glibc 2.17 has no <code>rcrt1.o</code>, so no <code>-static-pie</code>, and its <code>gcrt1.o</code> is not position-independent, so <code>-pg</code> needs <code>-no-pie</code> (<a href="./../reference/compatibility">compatibility</a>).</p><h3 id="on-windows-o-hello-wrote-hello-exe" tabindex="-1">On Windows, <code>-o hello</code> wrote <code>hello.exe</code> <a class="header-anchor" href="#on-windows-o-hello-wrote-hello-exe" aria-label="Permalink to &quot;On Windows, `-o hello` wrote `hello.exe`&quot;">​</a></h3><p>A MinGW link adds <code>.exe</code> to an output name without an extension. Name the output with its extension when cross-compiling (<code>-o hello.exe</code>).</p><h3 id="rust-undefined-unwind-symbols-linking-for-linux" tabindex="-1">Rust: undefined <code>_Unwind_*</code> symbols linking for Linux <a class="header-anchor" href="#rust-undefined-unwind-symbols-linking-for-linux" aria-label="Permalink to &quot;Rust: undefined `_Unwind_*` symbols linking for Linux&quot;">​</a></h3><p>Rust&#39;s standard library links with <code>-nodefaultlibs</code> and asks for <code>-lgcc_s</code>, which is an empty archive in xclang&#39;s sysroots. Name libunwind: <code>-Clink-arg=-l:libunwind.a</code> (<a href="./../integrations/cargo">Rust and cargo</a>).</p><h3 id="i-want-the-system-s-headers-and-libstdc-not-xclang-s" tabindex="-1">I want the system&#39;s headers and libstdc++, not xclang&#39;s <a class="header-anchor" href="#i-want-the-system-s-headers-and-libstdc-not-xclang-s" aria-label="Permalink to &quot;I want the system&#39;s headers and libstdc++, not xclang&#39;s&quot;">​</a></h3><p><code>--no-default-config</code> skips the target&#39;s config file and gives the bare compiler, which uses the system&#39;s headers and libraries as upstream clang does.</p><h2 id="cross-compiling" tabindex="-1">Cross-compiling <a class="header-anchor" href="#cross-compiling" aria-label="Permalink to &quot;Cross-compiling&quot;">​</a></h2><h3 id="windows-h-file-not-found-from-linux-but-it-builds-on-windows" tabindex="-1"><code>&#39;Windows.h&#39; file not found</code> from Linux, but it builds on Windows <a class="header-anchor" href="#windows-h-file-not-found-from-linux-but-it-builds-on-windows" aria-label="Permalink to &quot;`&#39;Windows.h&#39; file not found` from Linux, but it builds on Windows&quot;">​</a></h3><p>Windows file names ignore case; MinGW-w64&#39;s headers are lower case (<code>windows.h</code>, <code>basetsd.h</code>). Include them in lower case, which works everywhere (<a href="./../design/windows#case-sensitive-headers">Windows</a>).</p><h3 id="a-macos-target-fails-on-linux-or-windows" tabindex="-1">A macOS target fails on Linux or Windows <a class="header-anchor" href="#a-macos-target-fails-on-linux-or-windows" aria-label="Permalink to &quot;A macOS target fails on Linux or Windows&quot;">​</a></h3><p>The macOS targets build against Xcode&#39;s SDK, so on macOS hosts only, today (<a href="./../design/macos">macOS</a>). Building for macOS from other hosts, with the SDK fetched from Apple, is in research.</p><h3 id="linking-against-the-macos-27-sdk-fails-malformed-file-arm64e-x1" tabindex="-1">Linking against the macOS 27 SDK fails: &quot;malformed file&quot;, &quot;arm64e.x1&quot; <a class="header-anchor" href="#linking-against-the-macos-27-sdk-fails-malformed-file-arm64e-x1" aria-label="Permalink to &quot;Linking against the macOS 27 SDK fails: &quot;malformed file&quot;, &quot;arm64e.x1&quot;&quot;">​</a></h3><p>Xcode 27&#39;s SDK lists an architecture LLVM 23.1.2 does not know; 23.1.2.6 and later carry the fix (<a href="./../design/patches">patch 0009</a>).</p><h3 id="test-registrations-disappear-from-windows-release-builds" tabindex="-1">Test registrations disappear from Windows release builds <a class="header-anchor" href="#test-registrations-disappear-from-windows-release-builds" aria-label="Permalink to &quot;Test registrations disappear from Windows release builds&quot;">​</a></h3><p>lld&#39;s <code>--gc-sections</code> drops static initializers of unreferenced COMDAT sections for MinGW targets. The Bazel module leaves it off for Windows; in another build, do not pass <code>-Wl,--gc-sections</code> for Windows targets (<a href="./../design/windows#gc-sections-and-static-initializers">Windows</a>).</p><h2 id="sanitizers-and-debugging" tabindex="-1">Sanitizers and debugging <a class="header-anchor" href="#sanitizers-and-debugging" aria-label="Permalink to &quot;Sanitizers and debugging&quot;">​</a></h2><h3 id="asan-reports-a-container-overflow-that-is-not-there" tabindex="-1">ASan reports a container-overflow that is not there <a class="header-anchor" href="#asan-reports-a-container-overflow-that-is-not-there" aria-label="Permalink to &quot;ASan reports a container-overflow that is not there&quot;">​</a></h3><p>The program links the normal, uninstrumented <code>libc++.a</code>. Compile and link with libc++&#39;s ASan build: <code>-isystem &lt;asan&gt;/include</code> and <code>-nostdlib++ &lt;asan&gt;/libc++.a</code>, for every library of the program; Bazel&#39;s <code>--features=asan</code> does it (<a href="./../features/sanitizers">sanitizers</a>).</p><h3 id="gdb-or-lldb-does-not-find-the-sources-of-a-bazel-build" tabindex="-1">gdb or lldb does not find the sources of a Bazel build <a class="header-anchor" href="#gdb-or-lldb-does-not-find-the-sources-of-a-bazel-build" aria-label="Permalink to &quot;gdb or lldb does not find the sources of a Bazel build&quot;">​</a></h3><p>Paths in the debug information are relative to the execution root. Map <code>.</code> to the workspace&#39;s <code>bazel-&lt;workspace&gt;</code> link (<a href="./../integrations/bazel#debugging">Bazel</a>).</p><h3 id="a-macos-dsym-has-no-lines-for-code-compiled-with-thinlto" tabindex="-1">A macOS dSYM has no lines for code compiled with ThinLTO <a class="header-anchor" href="#a-macos-dsym-has-no-lines-for-code-compiled-with-thinlto" aria-label="Permalink to &quot;A macOS dSYM has no lines for code compiled with ThinLTO&quot;">​</a></h3><p>A dSYM made after the link misses the LTO objects, which the linker has deleted. Make it in the link: <code>xclang_debug_symbols</code> in CMake, the <code>generate_dsym_file</code> feature in Bazel (<a href="./../features/debugging#why-a-dsym-comes-from-the-link">debugging</a>).</p><h3 id="a-tool-that-reads-clang-fails" tabindex="-1">A tool that reads <code>clang -###</code> fails <a class="header-anchor" href="#a-tool-that-reads-clang-fails" aria-label="Permalink to &quot;A tool that reads `clang -###` fails&quot;">​</a></h3><p>clang prints its compile job as <code>&quot;.../llvm&quot; &quot;clang&quot; &quot;-cc1&quot; ...</code>, the multi-call program with the tool&#39;s name first. Skip the name (<a href="./../design/toolchain#one-program">the toolchain&#39;s shape</a>).</p><h2 id="build-speed-and-caches" tabindex="-1">Build speed and caches <a class="header-anchor" href="#build-speed-and-caches" aria-label="Permalink to &quot;Build speed and caches&quot;">​</a></h2><h3 id="linking-a-tool-on-libclang-takes-minutes-every-time" tabindex="-1">Linking a tool on libclang takes minutes every time <a class="header-anchor" href="#linking-a-tool-on-libclang-takes-minutes-every-time" aria-label="Permalink to &quot;Linking a tool on libclang takes minutes every time&quot;">​</a></h3><p>libclang is ThinLTO bitcode, and its code is generated at the link. Turn on the ThinLTO cache, <code>XCLANG_THINLTO_CACHE</code> (<a href="./../features/thinlto-cache">the ThinLTO cache</a>).</p><h3 id="the-thinlto-cache-does-nothing-under-bazel-on-linux" tabindex="-1">The ThinLTO cache does nothing under Bazel on Linux <a class="header-anchor" href="#the-thinlto-cache-does-nothing-under-bazel-on-linux" aria-label="Permalink to &quot;The ThinLTO cache does nothing under Bazel on Linux&quot;">​</a></h3><p>The sandbox lets a link write the directory only with <code>--sandbox_writable_path=&lt;dir&gt;</code>, and a directory under <code>/tmp</code> is the action&#39;s private <code>/tmp</code>, lost after the link. Use <code>/var/tmp/...</code> with <code>--sandbox_writable_path</code> (<a href="./../integrations/bazel#the-thinlto-cache">Bazel</a>).</p><h3 id="ccache-gives-a-wrong-program-after-a-module-s-interface-changed" tabindex="-1">ccache gives a wrong program after a module&#39;s interface changed <a class="header-anchor" href="#ccache-gives-a-wrong-program-after-a-module-s-interface-changed" aria-label="Permalink to &quot;ccache gives a wrong program after a module&#39;s interface changed&quot;">​</a></h3><p>ccache 4.13 and older serve an importer&#39;s object from before the change; 4.14 recompiles it. Neither caches module interfaces (<a href="./../features/modules#build-caches-and-modules">C++20 modules</a>).</p><h3 id="c-26-was-disabled-in-precompiled-file-or-another-option-mismatch-with-import-std" tabindex="-1"><code>C++26 was disabled in precompiled file</code>, or another option mismatch with <code>import std</code> <a class="header-anchor" href="#c-26-was-disabled-in-precompiled-file-or-another-option-mismatch-with-import-std" aria-label="Permalink to &quot;`C++26 was disabled in precompiled file`, or another option mismatch with `import std`&quot;">​</a></h3><p>The <code>std</code> module was built with other language options than the importer: <code>-std</code>, exceptions, RTTI. Set them project-wide (CMake), in <code>--cxxopt</code> (Bazel), or give the target a <code>std</code> of its own (<code>xclang_add_std</code>) (<a href="./../integrations/cmake#import-std">CMake</a>).</p><h2 id="windows-hosts" tabindex="-1">Windows hosts <a class="header-anchor" href="#windows-hosts" aria-label="Permalink to &quot;Windows hosts&quot;">​</a></h2><h3 id="bazel-fails-with-paths-too-long" tabindex="-1">Bazel fails with paths too long <a class="header-anchor" href="#bazel-fails-with-paths-too-long" aria-label="Permalink to &quot;Bazel fails with paths too long&quot;">​</a></h3><p>Bazel&#39;s default output root is too deep; put <code>startup --output_user_root=C:/b</code> in <code>%USERPROFILE%\\.bazelrc</code> (<a href="./../integrations/bazel#setup">Bazel</a>).</p><h3 id="killed-builds-left-llvm-exe-processes-behind" tabindex="-1">Killed builds left <code>llvm.exe</code> processes behind <a class="header-anchor" href="#killed-builds-left-llvm-exe-processes-behind" aria-label="Permalink to &quot;Killed builds left `llvm.exe` processes behind&quot;">​</a></h3><p>Fixed in 23.1.2.4: the launchers create <code>llvm.exe</code> inside a kill-on-close job (<a href="./../design/windows#the-launchers">Windows</a>).</p>',51)])])}const g=a(n,[["render",s]]);export{f as __pageData,g as default};
